<?php require 'bootstrap.php';if(user()){header('Location: channels.php');exit;}$err='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$nick=trim((string)($_POST['nickname']??''));$email=trim((string)($_POST['email']??''));$pass=(string)($_POST['password']??'');if(!valid_nick($nick))$err='Nickname ungültig (2–31 Zeichen).';elseif(!filter_var($email,FILTER_VALIDATE_EMAIL))$err='E-Mail ungültig.';elseif(strlen($pass)<10)$err='Passwort muss mindestens 10 Zeichen haben.';else{try{db()->beginTransaction();$q=db()->prepare("INSERT INTO ls_users(username,username_normalized,email,password_hash) VALUES(?,?,?,?)");$q->execute([$nick,norm_nick($nick),$email,password_hash($pass,PASSWORD_ARGON2ID)]);$uid=(int)db()->lastInsertId();$q=db()->prepare("INSERT INTO ls_nicknames(user_id,nickname,nickname_normalized,is_primary) VALUES(?,?,?,1)");$q->execute([$uid,$nick,norm_nick($nick)]);db()->commit();session_regenerate_id(true);$_SESSION['uid']=$uid;header('Location: channels.php?welcome=1');exit;}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();$err=str_contains($e->getMessage(),'Duplicate')?'Nickname oder E-Mail bereits registriert.':'Registrierung fehlgeschlagen.';}}}$title='Nickname registrieren';require 'header.php';?><section class="panel narrow"><span>WEB REGISTRATION</span><h1>Nickname registrieren</h1><p>Dieser Account ist deine IRC-Identität.</p><?php if($err):?><div class="error"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><label>Nickname<input name="nickname" maxlength="31" required autocomplete="nickname"></label><label>E-Mail<input name="email" type="email" maxlength="190" required autocomplete="email"></label><label>Passwort<input name="password" type="password" minlength="10" required autocomplete="new-password"></label><button>Account erstellen</button></form></section><?php require 'footer.php';?>
